INPUTS=[];CAPTURES=[]
def request(track=False):return {'op':'finish_timeline_wave','target':'source','parameters':{'finish_and_skip':False,'track_source_at_next_wave':track,'track_source_wave_delta':0,'track_all_managed_at_next_wave':False}}
def package(track=False):
 return {'schemaVersion':2,'manifest':{'id':'package/peer/wavetrack','requires':['preset/ark_standard']},'rules':[{'id':'rule/peer/restore','kind':'rule','contract':'resource.recovery','implementation':{'type':'expression','expression':'inputs.parameters.capacity * inputs.parameters.ratio'}}],'buffs':[{'id':'buff/peer/protect','kind':'buff','duration_seconds':2/30,'on_remove':[request(track)]}],'entities':[{'id':'unit/peer/source','kind':'entity','components':{'spatial':{},'attributes':{'base':{'max_hp':2500,'atk':53,'def':31,'mres':17}},'resources':{'hp':{'initial':2500,'capacity':2500,'role':'health'}},'lifecycle':{'policy':'policy/ark_lifecycle'},'abilities':['ability/peer/false','ability/peer/true'],'rebirth':{'resource':'hp','max_count':1,'delay_seconds':15/30,'restore_ratio':.5,'restore_rule':'rule/peer/restore','retain_buffs':['buff/peer/protect'],'on_begin':[{'op':'apply_buff','target':'self','buff':'buff/peer/protect'}]}}},{'id':'unit/peer/late','kind':'entity','components':{'spatial':{},'attributes':{'base':{'max_hp':100,'atk':0}},'resources':{'hp':{'initial':100,'capacity':100,'role':'health'}},'lifecycle':{'policy':'policy/ark_lifecycle'}}},{'id':'unit/peer/director','kind':'entity','components':{'spatial':{},'abilities':['ability/peer/kill','ability/peer/foreign']}}],'abilities':[{'id':'ability/peer/false','kind':'ability','activation':{'mode':'manual','on_start':[request(False)]},'timeline':[]},{'id':'ability/peer/true','kind':'ability','activation':{'mode':'manual','on_start':[request(track)]},'timeline':[]},{'id':'ability/peer/kill','kind':'ability','activation':{'mode':'manual','on_start':[{'op':'instant_kill','target':3,'parameters':{'cause':'peer_track','skip_rebirth':False}}]},'timeline':[]},{'id':'ability/peer/foreign','kind':'ability','activation':{'mode':'manual','on_start':[request(track)]},'timeline':[]}],'scenarioDraft':{'id':'scene/peer/wavetrack','ruleset':'ruleset/ark_standard','objectives':{},'map':{'rows':1,'cols':4},'initialEntities':[{'definition':'unit/peer/director','instanceAlias':'director','position':{'row':0,'col':0}}],'timeline':{'policy':'managed_clear','negative_timeout_policy':'wait_for_clear','waves':[{'pre_delay_seconds':0,'post_delay_seconds':4/30,'max_wait_seconds':-1,'fragments':[{'pre_delay_seconds':1/30,'actions':[{'kind':'spawn','count':1,'delay_seconds':2/30,'interval_seconds':0,'managed':True,'blocks_wave':True,'blocks_fragment':False,'spawn':{'definition':'unit/peer/source','position':{'row':0,'col':1},'instanceAlias':'managed_source'}},{'kind':'spawn','count':1,'delay_seconds':9/30,'interval_seconds':0,'managed':True,'blocks_wave':False,'blocks_fragment':False,'spawn':{'definition':'unit/peer/late','position':{'row':0,'col':2},'instanceAlias':'late_birth'}}]}]},{'pre_delay_seconds':3/30,'post_delay_seconds':0,'max_wait_seconds':-1,'fragments':[{'pre_delay_seconds':2/30,'actions':[{'kind':'spawn','count':1,'delay_seconds':0,'interval_seconds':0,'managed':True,'blocks_wave':True,'blocks_fragment':False,'spawn':{'definition':'unit/peer/late','position':{'row':0,'col':3},'instanceAlias':'next_birth'}}]}]}]}}}
def make(p=None):p=p or package();INPUTS.append(deepcopy(p));return Engine.create(Compiler().compile(p),seed=8882500)
def capture(s,name):CAPTURES.append({'case':name,'checkpoint':s.checkpoint(),'events':thaw(tuple(s.session.events)),'replay':s.export_replay()})
def test_original_false_request_keeps_source_on_wave0_and_preserves_remainingbirth_post_pre_cp_head(tmp_path):
 s=make();s.submit({'action':'skill','source':'director','ability':'ability/peer/kill'},at=6);s.advance(9);assert not s.ctx.active('managed_source') and s.ctx.resources.current('managed_source','hp')==0
 pin=write_ordered(tmp_path/'false9.json',s.checkpoint());r=Engine.restore(s.program,load_bound(tmp_path/'false9.json',pin));s.advance(16);r.advance(16);h=replay(s.program,s.export_replay());capture(s,'false');assert s.checkpoint()==r.checkpoint()==h.checkpoint()
 state=s.ctx.state()['timeline'];assert state['wave_index']==1 and state['members']['3']['wave']==0 and not state.get('tracking_requests',{})
 assert s.ctx.resources.current('managed_source','hp')==1250 and s.ctx.active('managed_source')
 births=[(e['time'],e['payload']['target']) for e in s.session.events if e['type']=='entity.created'];assert (3,3) in births and (10,4) in births and (19,5) in births
def public_kill(s):s.submit({'action':'skill','source':'director','ability':'ability/peer/kill'},at=6)
def equality(s,tmp_path,split=9,end=25):
 s.advance(split);pin=write_ordered(tmp_path/'track.cp.json',s.checkpoint());r=Engine.restore(s.program,load_bound(tmp_path/'track.cp.json',pin));s.advance(end-split);r.advance(end-split);h=replay(s.program,s.export_replay());assert s.checkpoint()==r.checkpoint()==h.checkpoint();return s
def test_actual_HP0_true_transfer_sameactor_to_wave1_at14_before_pre_and_birth19(tmp_path):
 s=make(package(True));public_kill(s);s.advance(9);assert s.ctx.resources.current('managed_source','hp')==0 and not s.ctx.active('managed_source');pin=write_ordered(tmp_path/'true9.json',s.checkpoint());r=Engine.restore(s.program,load_bound(tmp_path/'true9.json',pin));s.advance(11);r.advance(11);assert s.ctx.resources.current('managed_source','hp')==0 and not s.ctx.active('managed_source') and s.ctx.state()['timeline']['members']['3']['wave']==1
 s.advance(5);r.advance(5);h=replay(s.program,s.export_replay());capture(s,'true');assert s.checkpoint()==r.checkpoint()==h.checkpoint()
 events=[e for e in s.session.events if e['type']=='timeline.source_transferred'];assert len(events)==1 and events[0]['time']==14 and events[0]['payload']['source']==3
 assert s.ctx.state()['timeline']['tracking_requests']['0']['status']=='transferred' and s.ctx.resources.current('managed_source','hp')==1250
@pytest.mark.parametrize('sequence',[(False,True,True),(True,False,True),(True,True,False)])
def test_same_actual_source_strong_intent_upgrade_idempotent_never_downgrades(sequence):
 p=package(True);p['buffs'][0]['on_remove']=[];s=make(p);s.advance(7)
