 s.advance(13);capture(s,'intent_'+str(sequence));state=s.ctx.state()['timeline'];assert state['finish_requests']['0']['parameters']['track_source_at_next_wave'] is True and state['members']['3']['wave']==1
 assert len([e for e in s.session.events if e['type']=='timeline.source_transferred'])==1
