 p=package(True);p['scenarioDraft']['timeline']['waves']=p['scenarioDraft']['timeline']['waves'][:1];s=make(p);public_kill(s);equality(s,tmp_path);capture(s,'last');row=s.ctx.state()['timeline']['tracking_requests']['0'];assert row['status']=='no_next_wave'
 assert not any(e['type']=='timeline.source_transferred' for e in s.session.events) and len([e for e in s.session.events if e['type']=='entity.created'])==3
