def objective(inputs,params,context):return {'finished':context['time']>=9,'result':'defeat' if context['time']>=9 else 'ongoing','reason':'peer_time_limit'}
def test_no_controls_actual_objective_terminal_cancels_pending_tracking_and_keeps_birth_evidence(tmp_path):
 from ark_sim.domains.providers import BUILTIN_PROVIDERS
 p=package(True);p['rules'].append({'id':'rule/peer/terminal','kind':'rule','contract':'lifecycle.result','implementation':{'type':'provider','provider':'peer.terminal'}});p['scenarioDraft']['rules']={'lifecycle.result':'rule/peer/terminal'};p['scenarioDraft']['objectives']={'peer_finish_at':9};INPUTS.append(deepcopy(p));reg={**BUILTIN_PROVIDERS,'peer.terminal':objective};program=Compiler(providers=reg).compile(p);s=Engine.create(program,providers=reg);public_kill(s);s.advance(9);pin=write_ordered(tmp_path/'terminal9.json',s.checkpoint());r=Engine.restore(program,load_bound(tmp_path/'terminal9.json',pin),providers=reg);s.advance(6);r.advance(6);h=replay(program,s.export_replay(),providers=reg);capture(s,'no_control_terminal');assert s.checkpoint()==r.checkpoint()==h.checkpoint()
 assert s.ctx.controls is None and s.ctx.state()['finished'] and s.ctx.state()['timeline']['phase']=='stopped' and s.ctx.state()['timeline']['tracking_requests']['0']['status']=='terminal_cancelled'
 assert not any(e['type']=='timeline.source_transferred' for e in s.session.events) and not any(t['kind'].startswith('domain.timeline.') for t in s.session.scheduler.pending)
